head.script:
{
  "@context": "https://schema.org",
  "@type": "WebSite",
  "name": "PO ZipCode Global",
  "url": "https://zipcodeglobal.com",
  "description": "World's #1 PIN Code Finder — 121 countries, voice search, auto map",
  "potentialAction": {
    "@type": "SearchAction",
    "target": "https://zipcodeglobal.com/?q={search_term_string}",
    "query-input": "required name=search_term_string"
  }
}

head.b:skin:
/* ============================================
   ZIP CODE GLOBAL v6 — WORLD EDITION
   121 Countries · One Page Each
   Indian Heritage × Global Reach
   ============================================ */

:root {
  --saffron: #ff6b1a;
  --saffron-bright: #ff8c42;
  --saffron-glow: #ffb380;
  --gold: #f5b700;
  --gold-light: #ffd966;
  --royal-indigo: #1a1f4d;
  --royal-purple: #2d1b69;
  --peacock-teal: #0a9396;
  --peacock-blue: #006d77;
  --vermillion: #c1272d;
  --lotus: #e83e8c;
  --tulsi: #2d6a4f;
  --ivory: #fff8e7;
  --cinema: #050816;

  --bg-base: #050816;
  --bg-night: #0a0e27;
  --bg-deep: #131838;
  --bg-card: rgba(255, 255, 255, 0.035);
  --bg-card-hi: rgba(255, 255, 255, 0.07);
  --bg-glass: rgba(255, 255, 255, 0.05);
  --bg-veil: rgba(5, 8, 22, 0.85);
  --border: rgba(255, 179, 102, 0.14);
  --border-hi: rgba(255, 179, 102, 0.35);

  --text: #f5f1e8;
  --text-2: #d4cfc0;
  --text-3: #8b8478;
  --text-dim: #5c5648;

  --grad-saffron: linear-gradient(135deg, #ff6b1a 0%, #f5b700 100%);
  --grad-tricolor: linear-gradient(135deg, #ff6b1a 0%, #f5f1e8 50%, #2d6a4f 100%);
  --grad-cinema: linear-gradient(135deg, #ff6b1a 0%, #f5b700 50%, #e83e8c 100%);
  --grad-global: linear-gradient(135deg, #ff6b1a 0%, #f5b700 33%, #2d6a4f 66%, #006d77 100%);
  --grad-globe: conic-gradient(from 0deg, #ff6b1a, #f5b700, #2d6a4f, #006d77, #c1272d, #ff6b1a);

  --shadow-sm: 0 4px 12px rgba(0, 0, 0, 0.4);
  --shadow-md: 0 12px 40px rgba(0, 0, 0, 0.5);
  --shadow-lg: 0 24px 80px rgba(0, 0, 0, 0.6);
  --shadow-saffron: 0 0 60px rgba(255, 107, 26, 0.4);

  --font-display: 'Cinzel', 'Space Grotesk', serif;
  --font-body: 'Inter', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;
  --font-sanskrit: 'Tiro Devanagari Hindi', serif;

  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-elastic: cubic-bezier(0.68, -0.55, 0.265, 1.55);
  --d-fast: 0.2s;
  --d-base: 0.4s;
  --d-slow: 0.8s;
  --d-grand: 1.4s;

  --container: 1400px;
  --r-sm: 8px;
  --r-md: 16px;
  --r-lg: 24px;
  --r-xl: 32px;
  --r-full: 999px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; }
body {
  font-family: var(--font-body);
  background: var(--bg-base);
  color: var(--text);
  line-height: 1.6;
  overflow-x: hidden;
  min-height: 100vh;
  position: relative;
}

body::before {
  content: '';
  position: fixed; inset: 0;
  background:
    radial-gradient(ellipse at 10% 20%, rgba(255, 107, 26, 0.15) 0%, transparent 50%),
    radial-gradient(ellipse at 90% 10%, rgba(245, 183, 0, 0.1) 0%, transparent 50%),
    radial-gradient(ellipse at 50% 90%, rgba(45, 106, 79, 0.12) 0%, transparent 50%),
    radial-gradient(ellipse at 20% 80%, rgba(45, 27, 105, 0.35) 0%, transparent 50%),
    radial-gradient(ellipse at 80% 60%, rgba(0, 109, 119, 0.15) 0%, transparent 50%);
  z-index: -2;
  pointer-events: none;
}

body::after {
  content: '';
  position: fixed; inset: 0;
  background-image:
    linear-gradient(rgba(245, 183, 0, 0.02) 1px, transparent 1px),
    linear-gradient(90deg, rgba(245, 183, 0, 0.02) 1px, transparent 1px);
  background-size: 80px 80px;
  z-index: -1;
  pointer-events: none;
  mask-image: radial-gradient(ellipse at center, black 0%, transparent 80%);
  -webkit-mask-image: radial-gradient(ellipse at center, black 0%, transparent 80%);
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; color: inherit; }
input, select, textarea { font-family: inherit; }

::selection { background: var(--saffron); color: white; }
::-webkit-scrollbar { width: 12px; }
::-webkit-scrollbar-track { background: var(--bg-night); }
::-webkit-scrollbar-thumb { background: var(--grad-saffron); border-radius: var(--r-full); }

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-display);
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: -0.02em;
  color: var(--text);
}

.gradient-text {
  background: var(--grad-cinema);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
.global-text {
  background: var(--grad-global);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.kicker {
  display: inline-flex; align-items: center; gap: 0.5rem;
  font-family: var(--font-mono);
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--saffron-bright);
  padding: 0.625rem 1.25rem;
  border: 1px solid var(--border-hi);
  border-radius: var(--r-full);
  background: var(--bg-glass);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
}
.kicker::before { content: '◆'; font-size: 0.6rem; color: var(--gold); }

.container { width: 100%; max-width: var(--container); margin: 0 auto; padding: 0 1.5rem; }
.section { padding: 5rem 0; position: relative; }
.section-header { text-align: center; margin-bottom: 3rem; }
.section-header h2 { font-size: clamp(2rem, 4.5vw, 3rem); margin: 1.25rem 0; }
.section-header p { color: var(--text-3); max-width: 640px; margin: 0 auto; font-size: 1rem; }

/* NAV */
.cinema-nav {
  position: fixed; top: 0; left: 0; right: 0;
  z-index: 100;
  padding: 1.25rem 0;
  transition: all var(--d-base) var(--ease-out);
}
.cinema-nav.scrolled {
  background: var(--bg-veil);
  backdrop-filter: blur(24px) saturate(180%);
  -webkit-backdrop-filter: blur(24px) saturate(180%);
  border-bottom: 1px solid var(--border);
}
.cinema-nav .container { display: flex; align-items: center; justify-content: space-between; gap: 2rem; }

.brand {
  display: flex; align-items: center; gap: 0.875rem;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.375rem;
  color: var(--text);
}

.brand-mark {
  width: 44px; height: 44px;
  border-radius: 12px;
  background: var(--grad-saffron);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem;
  box-shadow: var(--shadow-saffron);
  animation: brand-pulse 4s ease-in-out infinite;
  position: relative;
}
.brand-mark::after {
  content: ''; position: absolute; inset: -4px;
  border-radius: 16px;
  border: 1px solid var(--saffron);
  opacity: 0.5;
  animation: brand-ring 4s ease-in-out infinite;
}
@keyframes brand-pulse {
  0%, 100% { box-shadow: 0 0 30px rgba(255, 107, 26, 0.4); }
  50% { box-shadow: 0 0 60px rgba(255, 107, 26, 0.7); }
}
@keyframes brand-ring {
  0%, 100% { transform: scale(1); opacity: 0.5; }
  50% { transform: scale(1.2); opacity: 0; }
}

.nav-actions { display: flex; align-items: center; gap: 0.5rem; }
.nav-btn {
  height: 44px; padding: 0 1rem;
  border-radius: var(--r-full);
  background: var(--bg-glass);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border: 1px solid var(--border);
  display: flex; align-items: center; gap: 0.5rem;
  font-size: 0.9rem;
  color: var(--text);
  transition: all var(--d-fast) var(--ease-out);
}
.nav-btn:hover { background: var(--bg-card-hi); border-color: var(--saffron); }
.nav-btn .kbd {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  padding: 0.125rem 0.375rem;
  background: var(--bg-card-hi);
  border-radius: 4px;
  color: var(--text-3);
}

/* INTRO */
.intro-overlay {
  position: fixed; inset: 0;
  z-index: 9999;
  background: var(--cinema);
  display: flex; align-items: center; justify-content: center;
  flex-direction: column;
  gap: 1.5rem;
  transition: opacity 0.8s var(--ease-out), visibility 0.8s;
}
.intro-overlay.hidden { opacity: 0; visibility: hidden; pointer-events: none; }

.intro-globe {
  width: 160px; height: 160px;
  border-radius: 50%;
  background: var(--grad-globe);
  position: relative;
  box-shadow: 0 0 120px rgba(255, 107, 26, 0.7), inset 0 0 60px rgba(0,0,0,0.4);
  animation: globe-rotate 3s linear infinite, intro-pulse 1.5s var(--ease-out) forwards;
  transform: scale(0);
}
.intro-globe::before, .intro-globe::after {
  content: '';
  position: absolute; inset: 0;
  border-radius: 50%;
  background-image:
    linear-gradient(rgba(255,255,255,0.15) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.15) 1px, transparent 1px);
  background-size: 20px 20px;
  mask-image: radial-gradient(ellipse at center, black 30%, transparent 70%);
  -webkit-mask-image: radial-gradient(ellipse at center, black 30%, transparent 70%);
}
.intro-globe::after {
  background-image: linear-gradient(rgba(0,0,0,0.2) 1px, transparent 1px), linear-gradient(90deg, rgba(0,0,0,0.2) 1px, transparent 1px);
  animation: globe-rotate 6s linear infinite reverse;
}
@keyframes globe-rotate { to { transform: rotate(360deg); } }
@keyframes intro-pulse {
  0% { transform: scale(0) rotate(-180deg); opacity: 0; }
  60% { transform: scale(1.1) rotate(0); opacity: 1; }
  100% { transform: scale(1); opacity: 1; }
}

.intro-text {
  font-family: var(--font-display);
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--text);
  background: var(--grad-cinema);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  opacity: 0;
  animation: intro-fade 0.8s var(--ease-out) 0.5s forwards;
}
@keyframes intro-fade { to { opacity: 1; } }

.intro-sub {
  font-family: var(--font-sanskrit);
  font-size: 1.1rem;
  color: var(--gold);
  opacity: 0;
  animation: intro-fade 0.8s var(--ease-out) 0.9s forwards;
}

.intro-bar {
  width: 240px; height: 2px;
  background: var(--bg-card-hi);
  border-radius: var(--r-full);
  overflow: hidden;
  opacity: 0;
  animation: intro-fade 0.8s var(--ease-out) 1.1s forwards;
}
.intro-bar::after {
  content: '';
  display: block;
  height: 100%;
  background: var(--grad-saffron);
  width: 0;
  animation: intro-progress 2.5s var(--ease-out) 1.3s forwards;
}
@keyframes intro-progress { to { width: 100%; } }

/* HERO */
.cinema-hero {
  min-height: 100vh;
  display: flex; align-items: center; justify-content: center;
  position: relative;
  padding: 7rem 1.5rem 3rem;
  overflow: hidden;
}

.hero-globe {
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  width: 700px; height: 700px;
  border-radius: 50%;
  background: var(--grad-globe);
  filter: blur(120px);
  opacity: 0.15;
  z-index: 0;
  animation: globe-glow 20s linear infinite;
}
@keyframes globe-glow {
  0%, 100% { transform: translate(-50%, -50%) scale(1) rotate(0); }
  50% { transform: translate(-50%, -50%) scale(1.2) rotate(180deg); }
}

#particles { position: absolute; inset: 0; z-index: 0; pointer-events: none; }

.cinema-content {
  position: relative;
  z-index: 1;
  text-align: center;
  max-width: 1100px;
}

.cinema-title {
  font-size: clamp(2.5rem, 7vw, 5.5rem);
  font-weight: 700;
  margin: 1.5rem 0;
  line-height: 0.95;
  letter-spacing: -0.03em;
}
.cinema-title .line {
  display: block;
  opacity: 0;
  transform: translateY(60px);
  animation: grand-reveal 1s var(--ease-out) forwards;
}
.cinema-title .line:nth-child(1) { animation-delay: 0.2s; }
.cinema-title .line:nth-child(2) { animation-delay: 0.5s; }
.cinema-title .line:nth-child(3) { animation-delay: 0.8s; }
@keyframes grand-reveal { to { opacity: 1; transform: translateY(0); } }

.cinema-subtitle {
  font-size: clamp(1rem, 1.8vw, 1.25rem);
  color: var(--text-2);
  max-width: 750px;
  margin: 0 auto 2.5rem;
  opacity: 0;
  animation: grand-reveal 1s var(--ease-out) 1.1s forwards;
  font-weight: 300;
}

.sanskrit-quote {
  display: block;
  font-family: var(--font-sanskrit);
  font-size: 1.1rem;
  color: var(--gold);
  margin-top: 0.75rem;
  font-style: italic;
  opacity: 0.85;
}

.hero-stats {
  display: flex; justify-content: center; gap: 3.5rem;
  margin-top: 2.5rem;
  opacity: 0;
  animation: grand-reveal 1s var(--ease-out) 1.3s forwards;
  flex-wrap: wrap;
}
.stat { text-align: center; transition: transform var(--d-fast) var(--ease-out); }
.stat:hover { transform: translateY(-4px); }
.stat-num {
  display: block;
  font-family: var(--font-display);
  font-size: 2.5rem;
  font-weight: 700;
  background: var(--grad-cinema);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  line-height: 1;
}
.stat-num.counter { font-variant-numeric: tabular-nums; }
.stat-label {
  font-size: 0.75rem;
  color: var(--text-3);
  text-transform: uppercase;
  letter-spacing: 0.15em;
  margin-top: 0.5rem;
}

/* COUNTRIES GRID — Rectangle boxes with flags */
.countries-toolbar {
  max-width: 800px;
  margin: 0 auto 2rem;
  display: flex; gap: 1rem; align-items: center;
  flex-wrap: wrap;
  justify-content: center;
}
.search-input {
  flex: 1; min-width: 250px;
  padding: 0.875rem 1.125rem 0.875rem 2.75rem;
  background: var(--bg-glass);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid var(--border-hi);
  border-radius: var(--r-full);
  color: var(--text);
  font-size: 0.95rem;
  outline: none;
  transition: all var(--d-fast) var(--ease-out);
  position: relative;
}
.search-wrap { position: relative; flex: 1; min-width: 250px; }
.search-wrap::before {
  content: '🔍';
  position: absolute;
  left: 1rem; top: 50%;
  transform: translateY(-50%);
  font-size: 1rem;
  z-index: 1;
}
.search-input:focus {
  border-color: var(--saffron);
  box-shadow: 0 0 0 4px rgba(255, 107, 26, 0.15);
}

.region-tabs {
  display: flex; gap: 0.4rem;
  flex-wrap: wrap;
  justify-content: center;
  margin-bottom: 2.5rem;
}
.region-tab {
  padding: 0.5rem 1rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--r-full);
  font-size: 0.8rem;
  color: var(--text-3);
  cursor: pointer;
  transition: all var(--d-fast) var(--ease-out);
  font-weight: 500;
}
.region-tab:hover { color: var(--text); border-color: var(--saffron); }
.region-tab.active {
  background: var(--grad-saffron);
  color: white;
  border-color: var(--saffron);
  box-shadow: 0 4px 20px rgba(255, 107, 26, 0.4);
}

.countries-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 0.875rem;
}

.country-btn {
  display: flex; align-items: center; gap: 0.875rem;
  padding: 1rem 1.25rem;
  background: var(--bg-card);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  cursor: pointer;
  transition: all var(--d-base) var(--ease-out);
  text-align: left;
  position: relative; overflow: hidden;
  opacity: 0; transform: translateY(20px);
}
.country-btn.revealed { opacity: 1; transform: translateY(0); }
.country-btn::before {
  content: '';
  position: absolute; inset: 0;
  background: var(--grad-saffron);
  opacity: 0;
  transition: opacity var(--d-base) var(--ease-out);
  z-index: 0;
}
.country-btn:hover {
  transform: translateY(-4px);
  border-color: var(--saffron);
  box-shadow: var(--shadow-md), 0 0 30px rgba(255, 107, 26, 0.15);
}
.country-btn:hover::before { opacity: 0.08; }
.country-btn.featured {
  background: linear-gradient(135deg, rgba(255, 107, 26, 0.1), rgba(245, 183, 0, 0.05));
  border-color: var(--saffron);
}

.country-flag {
  font-size: 2rem;
  line-height: 1;
  flex-shrink: 0;
  z-index: 1;
  filter: drop-shadow(0 2px 4px rgba(0,0,0,0.3));
}
.country-info { flex: 1; min-width: 0; z-index: 1; }
.country-name {
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--text);
  line-height: 1.2;
  margin-bottom: 0.25rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.country-code {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  color: var(--text-3);
  letter-spacing: 0.05em;
}
.country-arrow {
  color: var(--text-dim);
  font-size: 0.9rem;
  z-index: 1;
  transition: transform var(--d-fast) var(--ease-out);
}
.country-btn:hover .country-arrow { transform: translateX(4px); color: var(--saffron); }

/* COUNTRY PAGE */
.country-page { display: none; }
.country-page.active { display: block; }
.home-page.hidden { display: none; }

.country-header {
  padding: 9rem 1.5rem 3rem;
  text-align: center;
  position: relative;
}
.back-btn {
  display: inline-flex; align-items: center; gap: 0.5rem;
  padding: 0.625rem 1.25rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--r-full);
  color: var(--text-2);
  font-size: 0.9rem;
  margin-bottom: 2rem;
  cursor: pointer;
  transition: all var(--d-fast) var(--ease-out);
}
.back-btn:hover { background: var(--bg-card-hi); color: var(--text); border-color: var(--saffron); }

.country-hero-flag {
  font-size: 5rem;
  line-height: 1;
  margin-bottom: 1rem;
  filter: drop-shadow(0 8px 20px rgba(0,0,0,0.4));
  animation: flag-float 4s ease-in-out infinite;
}
@keyframes flag-float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-8px); }
}

.country-hero-title {
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 700;
  margin: 0.5rem 0;
}
.country-hero-subtitle {
  color: var(--text-3);
  font-size: 1.1rem;
  margin-bottom: 2rem;
}

.country-search-card {
  max-width: 700px;
  margin: 0 auto;
  background: var(--bg-glass);
  backdrop-filter: blur(24px) saturate(180%);
  -webkit-backdrop-filter: blur(24px) saturate(180%);
  border: 1px solid var(--border-hi);
  border-radius: var(--r-xl);
  padding: 2rem;
  box-shadow: var(--shadow-lg);
}
.country-search-row {
  display: flex; gap: 0.5rem;
  padding: 0.5rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--r-full);
}
.country-search-row input {
  flex: 1;
  padding: 0.875rem 1.25rem;
  background: transparent;
  border: none;
  outline: none;
  color: var(--text);
  font-size: 0.95rem;
  font-family: var(--font-mono);
}
.country-search-row button {
  padding: 0.875rem 1.5rem;
  background: var(--grad-saffron);
  color: white;
  border-radius: var(--r-full);
  font-weight: 600;
  cursor: pointer;
  transition: all var(--d-fast) var(--ease-out);
}
.country-search-row button:hover { transform: scale(1.05); box-shadow: 0 8px 24px rgba(255, 107, 26, 0.5); }

.country-states-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 0.75rem;
  max-width: 1000px;
  margin: 2rem auto 0;
}
.state-btn {
  padding: 1rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  color: var(--text-2);
  font-size: 0.9rem;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--d-fast) var(--ease-out);
  text-align: center;
}
.state-btn:hover {
  background: var(--bg-card-hi);
  border-color: var(--saffron);
  color: var(--text);
  transform: translateY(-2px);
}

/* MAP */
.map-section {
  margin: 2.5rem 0;
  opacity: 0;
  transform: translateY(30px);
  transition: all var(--d-grand) var(--ease-out);
  max-height: 0;
  overflow: hidden;
}
.map-section.visible { opacity: 1; transform: translateY(0); max-height: 700px; }
.map-wrapper {
  position: relative;
  border-radius: var(--r-xl);
  overflow: hidden;
  border: 1px solid var(--border-hi);
  box-shadow: var(--shadow-lg);
}
#map { height: 500px; width: 100%; z-index: 1; }
.map-badge {
  position: absolute; top: 1rem; left: 1rem;
  z-index: 1000;
  padding: 0.625rem 1.125rem;
  background: var(--bg-veil);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid var(--border-hi);
  border-radius: var(--r-full);
  font-family: var(--font-mono);
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text);
  display: flex; align-items: center; gap: 0.5rem;
}
.pulse-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 12px var(--gold);
  animation: pulse-dot 1.5s ease-in-out infinite;
}
@keyframes pulse-dot {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.6); opacity: 0.4; }
}
.leaflet-tile { filter: brightness(0.6) invert(1) contrast(1.3) hue-rotate(200deg) saturate(0.2) brightness(0.85); }
.leaflet-container { background: var(--bg-night) !important; font-family: var(--font-body) !important; }
.leaflet-control-attribution {
  background: var(--bg-veil) !important;
  backdrop-filter: blur(10px);
  color: var(--text-3) !important;
  font-size: 0.7rem !important;
}
.leaflet-popup-content-wrapper {
  background: var(--bg-night) !important;
  color: var(--text) !important;
  border-radius: var(--r-md) !important;
  border: 1px solid var(--border-hi) !important;
}
.leaflet-popup-tip { background: var(--bg-night) !important; }

/* RESULTS */
.results-section {
  margin: 2rem 0;
  opacity: 0;
  transform: translateY(20px);
  transition: all var(--d-grand) var(--ease-out);
  max-height: 0;
  overflow: hidden;
}
.results-section.visible { opacity: 1; transform: translateY(0); max-height: none; overflow: visible; }
.results-header {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 1.5rem; flex-wrap: wrap; gap: 1rem;
}
.results-title { font-size: 1.5rem; font-weight: 700; }
.results-count {
  padding: 0.5rem 1.125rem;
  background: var(--bg-card);
  border: 1px solid var(--border-hi);
  border-radius: var(--r-full);
  font-family: var(--font-mono);
  font-size: 0.85rem;
  color: var(--saffron-bright);
}
.results-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(360px, 1fr));
  gap: 1.25rem;
}
.result-card {
  background: var(--bg-card);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  padding: 1.5rem;
  transition: all var(--d-base) var(--ease-out);
  opacity: 0;
  transform: translateY(20px);
  animation: card-reveal 0.6s var(--ease-out) forwards;
}
@keyframes card-reveal { to { opacity: 1; transform: translateY(0); } }
.result-card:hover { transform: translateY(-4px); border-color: var(--saffron); box-shadow: var(--shadow-md); }
.result-pin {
  font-family: var(--font-mono);
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
  display: flex; align-items: center; gap: 0.625rem;
}
.result-pin-num {
  background: var(--grad-cinema);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
.copy-btn {
  width: 32px; height: 32px;
  border-radius: 8px;
  background: var(--bg-card-hi);
  border: 1px solid var(--border);
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 0.85rem;
  cursor: pointer;
  transition: all var(--d-fast) var(--ease-out);
}
.copy-btn:hover { background: var(--saffron); color: white; transform: scale(1.1); }
.copy-btn.copied { background: var(--peacock-teal); color: white; }
.result-office {
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text);
  margin-bottom: 0.25rem;
}
.result-meta {
  margin-top: 1rem;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.875rem;
  padding-top: 1rem;
  border-top: 1px solid var(--border);
}
.meta-item { font-size: 0.8rem; }
.meta-label { display: block; color: var(--text-3); font-size: 0.65rem; text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 0.2rem; font-weight: 600; }
.meta-value { color: var(--text-2); font-weight: 500; }
.result-actions {
  display: flex; gap: 0.4rem;
  margin-top: 1rem;
  padding-top: 1rem;
  border-top: 1px solid var(--border);
}
.action-btn {
  flex: 1;
  padding: 0.5rem 0.625rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--r-sm);
  color: var(--text-2);
  font-size: 0.75rem;
  font-weight: 500;
  display: flex; align-items: center; justify-content: center; gap: 0.3rem;
  cursor: pointer;
  transition: all var(--d-fast) var(--ease-out);
}
.action-btn:hover { background: var(--bg-card-hi); color: var(--text); border-color: var(--saffron); }
.empty-state, .loading-state {
  grid-column: 1 / -1;
  text-align: center;
  padding: 3rem 1rem;
  color: var(--text-3);
}
.spinner {
  width: 28px; height: 28px;
  border: 3px solid var(--border);
  border-top-color: var(--saffron);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
  margin: 0 auto 0.875rem;
}
@keyframes spin { to { transform: rotate(360deg); } }

/* TOAST */
.toast-container {
  position: fixed; top: 90px; right: 1.5rem;
  z-index: 1000;
  display: flex; flex-direction: column; gap: 0.5rem;
  pointer-events: none;
}
.toast {
  padding: 0.875rem 1.25rem;
  background: var(--bg-veil);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
  border: 1px solid var(--border-hi);
  border-radius: var(--r-md);
  color: var(--text);
  font-size: 0.9rem;
  display: flex; align-items: center; gap: 0.625rem;
  min-width: 280px;
  transform: translateX(120%);
  transition: transform var(--d-base) var(--ease-out);
  pointer-events: auto;
  font-weight: 500;
}
.toast.show { transform: translateX(0); }
.toast.success { border-color: var(--peacock-teal); }
.toast.error { border-color: var(--vermillion); }

/* FEATURES */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.5rem;
}
.feature-card {
  padding: 2.5rem 2rem;
  background: var(--bg-card);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border: 1px solid var(--border);
  border-radius: var(--r-md);
  text-align: center;
  transition: all var(--d-base) var(--ease-out);
}
.feature-card:hover { transform: translateY(-6px); border-color: var(--saffron); box-shadow: var(--shadow-md); }
.feature-icon {
  width: 64px; height: 64px;
  border-radius: 16px;
  background: var(--grad-saffron);
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 1.875rem;
  margin-bottom: 1.25rem;
  box-shadow: var(--shadow-saffron);
}
.feature-title {
  font-family: var(--font-display);
  font-weight: 600; font-size: 1.2rem;
  margin-bottom: 0.5rem;
}
.feature-desc { font-size: 0.9rem; color: var(--text-3); line-height: 1.7; }

/* FOOTER */
.cinema-footer {
  margin-top: 4rem;
  padding: 3rem 0 1.5rem;
  background: linear-gradient(180deg, transparent, var(--bg-night));
  border-top: 1px solid var(--border);
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 3rem; margin-bottom: 2.5rem;
}
.footer-brand p { color: var(--text-3); margin: 1.25rem 0; max-width: 360px; font-size: 0.9rem; line-height: 1.7; }
.footer-col h4 {
  font-family: var(--font-display);
  font-size: 0.8rem; font-weight: 600;
  text-transform: uppercase; letter-spacing: 0.15em;
  margin-bottom: 1.25rem;
  color: var(--saffron-bright);
}
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 0.625rem; }
.footer-col a { color: var(--text-3); font-size: 0.9rem; transition: color var(--d-fast) var(--ease-out); }
.footer-col a:hover { color: var(--saffron-bright); }
.footer-bottom {
  padding-top: 1.5rem;
  border-top: 1px solid var(--border);
  display: flex; justify-content: space-between; align-items: center;
  flex-wrap: wrap; gap: 1rem;
  font-size: 0.85rem; color: var(--text-3);
}
.tricolor-bar {
  height: 3px;
  background: linear-gradient(90deg, #ff6b1a 0%, #ff6b1a 33%, #f5f1e8 33%, #f5f1e8 66%, #2d6a4f 66%, #2d6a4f 100%);
  border-radius: var(--r-full);
  margin-top: 1.5rem;
  opacity: 0.5;
}

/* RESPONSIVE */
@media (max-width: 768px) {
  .section { padding: 3rem 0; }
  .cinema-hero { min-height: 90vh; padding: 6rem 1rem 2rem; }
  .hero-stats { gap: 1.5rem; }
  .stat-num { font-size: 1.75rem; }
  .hero-globe { width: 400px; height: 400px; }
  .toast-container { left: 1rem; right: 1rem; top: 80px; }
  .toast { min-width: auto; }
  .results-grid { grid-template-columns: 1fr; }
  .countries-grid { grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); }
  .country-btn { padding: 0.875rem 1rem; }
  .country-flag { font-size: 1.625rem; }
  .country-name { font-size: 0.85rem; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 2rem; }
  .footer-brand { grid-column: 1 / -1; }
  .country-search-card { padding: 1.25rem; }
  .country-search-row { flex-direction: column; border-radius: var(--r-md); }
  .country-search-row button { width: 100%; }
  #map { height: 350px; }
  .country-states-grid { grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); }
  .intro-globe { width: 120px; height: 120px; }
  .intro-text { font-size: 1.25rem; letter-spacing: 0.2em; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
}

.blogger-hidden { display: none !important; }

