  function showToast(message, type = 'info') {
    const container = $('toastContainer');
    const toast = document.createElement('div');
    toast.className = 'toast ' + type;
    const icon = type === 'success' ? '✓' : type === 'error' ? '✕' : 'ℹ';
    toast.innerHTML = `<span class="toast-icon">${icon}</span><span>${message}</span>`;
    container.appendChild(toast);
    setTimeout(() => toast.classList.add('show'), 10);
    setTimeout(() => { toast.classList.remove('show'); setTimeout(() => toast.remove(), 400); }, 3500);
  }

  function copyToClipboard(text) {
    if (navigator.clipboard) {
      navigator.clipboard.writeText(text).then(() => showToast(`Copied: ${text}`, 'success'));
    } else {
      const ta = document.createElement('textarea');
      ta.value = text;
      document.body.appendChild(ta);
      ta.select();
      try { document.execCommand('copy'); showToast(`Copied: ${text}`, 'success'); } catch (e) { showToast('Copy failed', 'error'); }
      document.body.removeChild(ta);
    }
  }

  setTimeout(() => $('introOverlay').classList.add('hidden'), 3500);

  function animateCounter(el) {
    const target = parseInt(el.dataset.target);
    const duration = 2000;
    const start = performance.now();
    function tick(now) {
      const t = Math.min((now - start) / duration, 1);
      const eased = 1 - Math.pow(1 - t, 3);
      el.textContent = Math.floor(target * eased).toLocaleString('en-IN') + '+';
      if (t < 1) requestAnimationFrame(tick);
      else el.textContent = target.toLocaleString('en-IN') + '+';
    }
    requestAnimationFrame(tick);
  }
  const counterObserver = new IntersectionObserver((entries) => {
    entries.forEach(e => { if (e.isIntersecting) { animateCounter(e.target); counterObserver.unobserve(e.target); } });
  }, { threshold: 0.5 });
  $$('.counter').forEach(c => counterObserver.observe(c));

  let scrollTimeout;
  window.addEventListener('scroll', () => {
    if (scrollTimeout) return;
    scrollTimeout = setTimeout(() => {
      if (window.scrollY > 50) $('cinemaNav').classList.add('scrolled');
      else $('cinemaNav').classList.remove('scrolled');
      scrollTimeout = null;
    }, 10);
  }, { passive: true });

  function initParticles() {
    const canvas = $('particles');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    let particles = [];
    function resize() {
      canvas.width = canvas.offsetWidth * window.devicePixelRatio;
      canvas.height = canvas.offsetHeight * window.devicePixelRatio;
      canvas.style.width = canvas.offsetWidth + 'px';
      canvas.style.height = canvas.offsetHeight + 'px';
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
    }
    class Particle {
      constructor(w, h) {
        this.x = Math.random() * w;
        this.y = Math.random() * h;
        this.size = Math.random() * 1.5 + 0.3;
        this.speedX = (Math.random() - 0.5) * 0.3;
        this.speedY = (Math.random() - 0.5) * 0.3;
        this.opacity = Math.random() * 0.4 + 0.15;
      }
      update(w, h) {
        this.x += this.speedX; this.y += this.speedY;
        if (this.x < 0 || this.x > w) this.speedX *= -1;
        if (this.y < 0 || this.y > h) this.speedY *= -1;
      }
      draw() {
        ctx.fillStyle = `rgba(255, 179, 102, ${this.opacity})`;
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx.fill();
      }
    }
    function init() {
      const w = canvas.offsetWidth, h = canvas.offsetHeight;
      particles = [];
      const count = Math.min(50, Math.floor((w * h) / 15000));
      for (let i = 0; i < count; i++) particles.push(new Particle(w, h));
    }
    function animate() {
      const w = canvas.offsetWidth, h = canvas.offsetHeight;
      ctx.clearRect(0, 0, w, h);
      particles.forEach(p => { p.update(w, h); p.draw(); });
      for (let i = 0; i < particles.length; i++) {
        for (let j = i + 1; j < particles.length; j++) {
          const dx = particles[i].x - particles[j].x;
          const dy = particles[i].y - particles[j].y;
          const dist = Math.sqrt(dx*dx + dy*dy);
          if (dist < 100) {
            ctx.strokeStyle = `rgba(255, 107, 26, ${0.12 * (1 - dist/100)})`;
            ctx.lineWidth = 0.5;
            ctx.beginPath();
            ctx.moveTo(particles[i].x, particles[i].y);
            ctx.lineTo(particles[j].x, particles[j].y);
            ctx.stroke();
          }
        }
      }
      requestAnimationFrame(animate);
    }
    resize(); init(); animate();
    let rt;
    window.addEventListener('resize', () => { clearTimeout(rt); rt = setTimeout(() => { resize(); init(); }, 200); });
  }
  initParticles();

  // ============ RENDER COUNTRIES GRID ============
  function renderRegionTabs() {
    $('regionTabs').innerHTML = REGIONS.map(r => `<button class="region-tab ${r === 'All' ? 'active' : ''}" data-region="${r}">${r}</button>`).join('');
    $$('.region-tab').forEach(tab => tab.addEventListener('click', () => {
      appState.region = tab.dataset.region;
      $$('.region-tab').forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
      renderCountries();
    }));
  }

  function renderCountries() {
    const search = ($('countrySearch').value || '').toLowerCase();
    let list = ALL_COUNTRIES;
    if (appState.region !== 'All') list = list.filter(c => c.region === appState.region);
    if (search) list = list.filter(c => c.name.toLowerCase().includes(search) || c.code.toLowerCase().includes(search));

    $('countriesGrid').innerHTML = list.map((c, i) => `
      <button class="country-btn ${c.featured ? 'featured' : ''}" data-code="${c.code}" style="transition-delay: ${Math.min(i, 30) * 12}ms">
        <span class="country-flag">${c.flag}</span>
        <div class="country-info">
          <div class="country-name">${c.name}</div>
          <div class="country-code">${c.code} · ${c.sample}</div>
        </div>
        <span class="country-arrow">→</span>
      </button>
    `).join('');

    const obs = new IntersectionObserver((entries) => {
      entries.forEach((entry, i) => { if (entry.isIntersecting) setTimeout(() => entry.target.classList.add('revealed'), i * 10); });
    }, { threshold: 0.05, rootMargin: '30px' });
    $$('.country-btn').forEach(c => obs.observe(c));

    $$('.country-btn').forEach(btn => btn.addEventListener('click', () => {
      const code = btn.dataset.code;
      openCountryPage(code);
    }));
  }

  $('countrySearch').addEventListener('input', renderCountries);

  // ============ COUNTRY PAGE ============
  async function openCountryPage(code) {
    const country = ALL_COUNTRIES.find(c => c.code === code);
    if (!country) return;

    appState.currentCountry = country;
    $('countryFlag').textContent = country.flag;
    $('countryTitle').textContent = country.name;
    $('countrySubtitle').textContent = country.subtitle || `${country.region} · Sample: ${country.sample}`;
    $('countryCodeInput').value = '';
    $('mapSection').classList.remove('visible');
    $('resultsSection').classList.remove('visible');
    $('countryStatesGrid').innerHTML = '<div class="loading-state" style="grid-column: 1/-1; text-align: center; padding: 2rem;"><div class="spinner"></div><p>Loading states...</p></div>';

    $('homePage').classList.add('hidden');
    $('countryPage').classList.add('active');
    $('backToWorld').style.display = 'inline-flex';
    window.scrollTo({ top: 0, behavior: 'smooth' });

    showMap([{ latitude: country.lat, longitude: country.lon, officename: country.name, pincode: country.sample }]);

    try {
      const stateFiles = await getStateFiles(country);
      appState.currentStateFiles = stateFiles;
      renderStateButtons(stateFiles);
    } catch (err) {
      $('countryStatesGrid').innerHTML = '<div class="loading-state" style="grid-column: 1/-1; text-align: center; padding: 2rem; color: var(--vermillion);">Could not load states. Try the search above.</div>';
    }
  }

  function closeCountryPage() {
    $('homePage').classList.remove('hidden');
    $('countryPage').classList.remove('active');
    $('backToWorld').style.display = 'none';
    window.scrollTo({ top: 0, behavior: 'smooth' });
    appState.currentCountry = null;
  }

  $('backBtn').addEventListener('click', closeCountryPage);
  $('backToWorld').addEventListener('click', closeCountryPage);
  $('brandHome').addEventListener('click', (e) => { if (appState.currentCountry) { e.preventDefault(); closeCountryPage(); } });
  $('footerHome').addEventListener('click', (e) => { if (appState.currentCountry) { e.preventDefault(); closeCountryPage(); } });

