    if (country.folder === 'ROOT_INDIA') {
      // India: use root files
      return await getIndiaStateFiles();
    } else if (country.folder === 'ROOT_USA') {
      return await getUsaStateFiles();
    } else {
      // World country: list files in world/CODE/ folder
      return await getWorldCountryFiles(country.folder);
    }
  }

