      'JP': ['Tokyo_To.json', 'Osaka_Fu.json', 'Kyoto_Fu.json', 'Hokkaido.json', 'Aichi_Ken.json', 'Fukuoka_Ken.json', 'Kanagawa_Ken.json', 'Saitama_Ken.json', 'Chiba_Ken.json', 'Hyogo_Ken.json'],
      'CN': ['Beijing.json', 'Shanghai.json', 'Guangdong.json', 'Sichuan.json', 'Zhejiang.json', 'Jiangsu.json', 'Shandong.json'],
      'BR': ['Acre.json', 'Alagoas.json', 'Amapá.json', 'Amazonas.json', 'Bahia.json', 'Ceará.json', 'Distrito_Federal.json', 'Espírito_Santo.json', 'Goiás.json', 'Maranhão.json', 'Mato_Grosso.json', 'Mato_Grosso_do_Sul.json', 'Minas_Gerais.json', 'Pará.json', 'Paraíba.json', 'Paraná.json', 'Pernambuco.json', 'Piauí.json', 'Rio_de_Janeiro.json', 'Rio_Grande_do_Norte.json', 'Rio_Grande_do_Sul.json', 'Rondônia.json', 'Roraima.json', 'Santa_Catarina.json', 'São_Paulo.json', 'Sergipe.json', 'Tocantins.json'],
      'RU': ['Moscow.json', 'Saint_Petersburg.json', 'Moscow_Oblast.json', 'Krasnodar_Krai.json', 'Sverdlovsk_Oblast.json'],
      'CA': ['Ontario.json', 'Quebec.json', 'British_Columbia.json', 'Alberta.json', 'Manitoba.json', 'Saskatchewan.json', 'Nova_Scotia.json', 'New_Brunswick.json'],
      'AU': ['New_South_Wales.json', 'Victoria.json', 'Queensland.json', 'Western_Australia.json', 'South_Australia.json', 'Tasmania.json', 'Australian_Capital_Territory.json', 'Northern_Territory.json'],
      'IT': ['Lombardy.json', 'Lazio.json', 'Campania.json', 'Sicily.json', 'Veneto.json', 'Piedmont.json', 'Emilia-Romagna.json', 'Tuscany.json'],
      'ES': ['Madrid.json', 'Catalonia.json', 'Andalusia.json', 'Valencia.json', 'Basque_Country.json', 'Galicia.json'],
      'MX': ['Aguascalientes.json', 'Baja_California.json', 'Chiapas.json', 'Chihuahua.json', 'Coahuila.json', 'Jalisco.json', 'Mexico_City.json', 'Nuevo_Leon.json', 'Puebla.json', 'Querétaro.json', 'Quintana_Roo.json', 'Sonora.json', 'Veracruz.json', 'Yucatán.json'],
      'AR': ['Buenos_Aires.json', 'Córdoba.json', 'Santa_Fe.json', 'Mendoza.json', 'Tucumán.json'],
      'TR': ['Istanbul.json', 'Ankara.json', 'Izmir.json', 'Bursa.json', 'Antalya.json'],
      'ID': ['Jakarta.json', 'West_Java.json', 'East_Java.json', 'Bali.json', 'Sumatra.json'],
      'KR': ['Seoul.json', 'Busan.json', 'Incheon.json', 'Daegu.json', 'Gwangju.json'],
      'TH': ['Bangkok.json', 'Chiang_Mai.json', 'Phuket.json', 'Pattaya.json'],
      'PK': ['Punjab.json', 'Sindh.json', 'Khyber_Pakhtunkhwa.json', 'Balochistan.json', 'Islamabad.json'],
      'BD': ['Dhaka.json', 'Chittagong.json', 'Khulna.json', 'Rajshahi.json'],
      'ZA': ['Gauteng.json', 'Western_Cape.json', 'KwaZulu-Natal.json', 'Eastern_Cape.json'],
    };
    const files = KNOWN[code] || ['Unknown_State.json'];
    return files.map(f => ({ name: f.replace('.json', '').replace(/_/g, ' '), file: f }));
  }

  function renderStateButtons(stateFiles) {
    $('countryStatesGrid').innerHTML = stateFiles.map((s, i) => `
      <button class="state-btn" data-file="${s.file}" data-name="${s.name}" style="transition-delay: ${Math.min(i, 20) * 15}ms">${s.name}</button>
    `).join('');

    $$('.state-btn').forEach(btn => btn.addEventListener('click', async () => {
      const file = btn.dataset.file;
      const name = btn.dataset.name;
      const country = appState.currentCountry;
      if (!country) return;

      const url = country.folder === 'ROOT_INDIA' ? DATA_BASE + file
                : country.folder === 'ROOT_USA' ? DATA_BASE + 'usa/' + file
                : DATA_BASE + 'world/' + country.folder + '/' + file;

      try {
        btn.textContent = '⏳ Loading...';
        const cacheKey = url;
        let data;
        if (dataCache.has(cacheKey)) data = dataCache.get(cacheKey);
        else {
          const res = await fetch(url);
          if (!res.ok) throw new Error('fetch failed');
          data = await res.json();
          dataCache.set(cacheKey, data);
        }
        const code = $('countryCodeInput').value.trim();
        let results = data;
        if (code) {
          const searchFields = ['pincode', 'ZipCode', 'zipcode', 'postcode', 'postalcode', 'Postcode', 'code'];
          const matched = data.filter(item => {
            for (const f of searchFields) { if (item[f] && String(item[f]).toLowerCase().includes(code.toLowerCase())) return true; }
            return false;
          });
          if (matched.length > 0) results = matched;
        }
        renderResults(results, `${country.flag} ${country.name} — ${name}`, code ? `code: ${code}` : null);
        btn.textContent = name;
      } catch (err) {
        showToast('Failed to load state data', 'error');
        btn.textContent = name;
      }
    }));
  }

  // ============ SEARCH WITHIN COUNTRY ============
  $('countrySearchBtn').addEventListener('click', async () => {
    const code = $('countryCodeInput').value.trim();
    if (!code) { showToast('Enter a postal code', 'error'); return; }
    const country = appState.currentCountry;
    if (!country) return;

    if (!appState.currentStateFiles || appState.currentStateFiles.length === 0) {
      showToast('States not loaded yet', 'error');
      return;
    }

    $('resultsList').innerHTML = '<div class="loading-state" style="grid-column: 1/-1; text-align: center; padding: 3rem;"><div class="spinner"></div><p>Searching all states...</p></div>';
    $('resultsSection').classList.add('visible');

    const allMatches = [];
    const searchFields = ['pincode', 'ZipCode', 'zipcode', 'postcode', 'postalcode', 'Postcode', 'code'];
    for (const sf of appState.currentStateFiles) {
      try {
        const url = country.folder === 'ROOT_INDIA' ? DATA_BASE + sf.file
                  : country.folder === 'ROOT_USA' ? DATA_BASE + 'usa/' + sf.file
                  : DATA_BASE + 'world/' + country.folder + '/' + sf.file;
        const cacheKey = url;
        let data;
        if (dataCache.has(cacheKey)) data = dataCache.get(cacheKey);
        else { const res = await fetch(url); if (res.ok) { data = await res.json(); dataCache.set(cacheKey, data); } }
        if (data) {
          for (const item of data) {
            for (const f of searchFields) {
              if (item[f] && String(item[f]).toLowerCase() === code.toLowerCase()) {
                allMatches.push(item); break;
              }
            }
          }
        }
      } catch (e) {}
    }
    renderResults(allMatches, `${country.flag} ${country.name} — Search: ${code}`, null);
  });

  $('countryCodeInput').addEventListener('keypress', (e) => { if (e.key === 'Enter') $('countrySearchBtn').click(); });

  // ============ MAP ============
  function initMap() {
    if (appState.mapInitialized) return;
    appState.map = L.map('map', { zoomControl: true, scrollWheelZoom: false }).setView([20.5937, 78.9629], 3);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { attribution: '© OpenStreetMap', maxZoom: 19 }).addTo(appState.map);
    appState.mapInitialized = true;
  }

  function makePin(color1, color2) {
    return L.divIcon({
      className: 'custom-marker',
      html: `<div style="background: linear-gradient(135deg, ${color1}, ${color2}); width: 28px; height: 28px; border-radius: 50% 50% 50% 0; transform: rotate(-45deg); box-shadow: 0 4px 16px ${color1}80; border: 3px solid white;"></div>`,
      iconSize: [28, 28], iconAnchor: [14, 28],
    });
  }

  function showMap(results) {
    initMap();
    appState.mapMarkers.forEach(m => appState.map.removeLayer(m));
    appState.mapMarkers = [];
    const withCoords = results.filter(r => r.latitude !== undefined && r.longitude !== undefined && r.latitude !== null && r.longitude !== null);
    if (withCoords.length === 0) { $('mapSection').classList.remove('visible'); return; }
    withCoords.forEach((item, i) => {
      const colors = i === 0 ? ['#ff6b1a', '#f5b700'] : ['#006d77', '#0a9396'];
      const lat = parseFloat(item.latitude);
      const lon = parseFloat(item.longitude);
      if (isNaN(lat) || isNaN(lon)) return;
      const popupContent = `<strong style="color: #f5b700;">${item.City || item.officename || item.OfficeName || 'Location'}</strong><br/><span style="color: #d4cfc0; font-size: 0.85rem;">${item.ZipCode || item.pincode || ''} • ${item.State || item.statename || ''}</span>`;
      const m = L.marker([lat, lon], { icon: makePin(...colors) }).addTo(appState.map).bindPopup(popupContent);
      appState.mapMarkers.push(m);
    });
    if (withCoords.length === 1) {
      const lat = parseFloat(withCoords[0].latitude), lon = parseFloat(withCoords[0].longitude);
      if (!isNaN(lat) && !isNaN(lon)) appState.map.setView([lat, lon], 6, { animate: true, duration: 1 });
    } else {
      const valid = withCoords.filter(r => !isNaN(parseFloat(r.latitude)) && !isNaN(parseFloat(r.longitude)));
      if (valid.length > 0) {
        const bounds = L.latLngBounds(valid.map(r => [parseFloat(r.latitude), parseFloat(r.longitude)]));
        appState.map.fitBounds(bounds, { padding: [50, 50], maxZoom: 6, animate: true, duration: 1 });
      }
    }
    $('mapBadgeText').textContent = `${withCoords.length} location${withCoords.length > 1 ? 's' : ''}`;
    $('mapSection').classList.add('visible');
    setTimeout(() => appState.map.invalidateSize(), 400);
  }

  // ============ RESULTS ============
  function renderResults(results, title, subtitle) {
    if (!results || results.length === 0) {
      $('resultsList').innerHTML = `<div class="empty-state"><div class="empty-icon">🔍</div><p>No results found.${subtitle ? ' Try a different code.' : ''}</p></div>`;
      $('resultsCount').textContent = '0 found';
      $('resultsTitle').textContent = title;
      $('resultsSection').classList.add('visible');
      $('mapSection').classList.remove('visible');
      return;
    }
    $('resultsTitle').textContent = title;
    $('resultsCount').textContent = `${results.length} found`;
    $('resultsList').innerHTML = results.map((item, idx) => {
      const pincode = item.pincode || item.ZipCode || item.zipcode || 'N/A';
      const office = item.officename || item.OfficeName || item.City || 'Location';
      const state = item.statename || item.State || '';
      const district = item.district || item.County || item.City || '';
      const circle = item.circlename || item.StateAbbr || '';
      const division = item.divisionname || '';
      const region = item.regionname || item.Country || '';
      const delivery = item.delivery || '';
      const hasCoords = item.latitude !== undefined && item.longitude !== undefined && item.latitude !== null && item.longitude !== null;
      return `
        <div class="result-card" style="animation-delay: ${idx * 50}ms">
          <div class="result-pin">
            <span class="result-pin-num">${pincode}</span>
            <button class="copy-btn" data-pin="${pincode}">📋</button>
          </div>
          <div class="result-office">${office}</div>
          <div class="result-meta">
            <div class="meta-item"><span class="meta-label">State</span><span class="meta-value">${state || 'N/A'}</span></div>
            <div class="meta-item"><span class="meta-label">District</span><span class="meta-value">${district || 'N/A'}</span></div>
            <div class="meta-item"><span class="meta-label">Region</span><span class="meta-value">${region || 'N/A'}</span></div>
            <div class="meta-item"><span class="meta-label">Abbr</span><span class="meta-value">${circle || 'N/A'}</span></div>
            <div class="meta-item"><span class="meta-label">Division</span><span class="meta-value">${division || 'N/A'}</span></div>
            <div class="meta-item"><span class="meta-label">Type</span><span class="meta-value">${delivery || 'PO'}</span></div>
          </div>
          <div class="result-actions">
            ${hasCoords ? `<button class="action-btn" data-action="map" data-lat="${item.latitude}" data-lon="${item.longitude}" data-label="${office}">🗺️ Focus</button>` : ''}
            <a class="action-btn" href="https://www.google.com/maps?q=${item.latitude || ''},${item.longitude || ''}" rel="noopener" target="_blank">🌍 Google</a>
            <a class="action-btn" href="mailto:reclaimedmindwithrelaxmusic@gmail.com?subject=Mistake: ${office}">⚠️ Report</a>
          </div>
        </div>
      `;
    }).join('');

    $$('.copy-btn').forEach(btn => btn.addEventListener('click', (e) => {
      e.stopPropagation();
      copyToClipboard(btn.dataset.pin);
      btn.classList.add('copied'); btn.textContent = '✓';
      setTimeout(() => { btn.classList.remove('copied'); btn.textContent = '📋'; }, 1500);
    }));
    $$('[data-action="map"]').forEach(btn => btn.addEventListener('click', () => {
      const lat = parseFloat(btn.dataset.lat), lon = parseFloat(btn.dataset.lon);
      showMap([{ latitude: lat, longitude: lon, officename: btn.dataset.label }]);
    }));
    $('resultsSection').classList.add('visible');
    showMap(results);
    setTimeout(() => $('resultsSection').scrollIntoView({ behavior: 'smooth', block: 'start' }), 100);
  }

  // ============ COMMAND PALETTE ============
  function openCmd() {
    $('cmdOverlay').classList.add('open');
    $('cmdInput').value = '';
    $('cmdInput').focus();
    renderCmd('');
  }
  function closeCmd() { $('cmdOverlay').classList.remove('open'); }
  function renderCmd(query) {
    const list = $('cmdList');
    let filtered = ALL_COUNTRIES.filter(c => !query || c.name.toLowerCase().includes(query.toLowerCase()) || c.code.toLowerCase().includes(query.toLowerCase()));
    filtered = filtered.slice(0, 12);
    list.innerHTML = filtered.map(c => `
      <div class="cmd-item" data-code="${c.code}">
        <span class="cmd-icon">${c.flag}</span>
        <div class="cmd-text">
          <div class="cmd-title">${c.name}</div>
          <div class="cmd-subtitle">${c.code} · ${c.region}</div>
        </div>
        <span class="cmd-kbd">${c.code}</span>
      </div>
    `).join('');
    if (filtered.length === 0) list.innerHTML = '<div class="cmd-item"><span class="cmd-icon">🔍</span><div class="cmd-text"><div class="cmd-title">No countries found</div></div></div>';
    $$('.cmd-item[data-code]').forEach(el => el.addEventListener('click', () => { closeCmd(); openCountryPage(el.dataset.code); }));
  }

  $('cmdTrigger').addEventListener('click', openCmd);
  $('cmdInput').addEventListener('input', (e) => renderCmd(e.target.value));
  $('cmdOverlay').addEventListener('click', (e) => { if (e.target.id === 'cmdOverlay') closeCmd(); });
  document.addEventListener('keydown', (e) => {
    if ((e.metaKey || e.ctrlKey) && e.key === 'k') { e.preventDefault(); openCmd(); }
    if (e.key === 'Escape') closeCmd();
  });

  // ============ INIT ============
  renderRegionTabs();
  renderCountries();
  $('year').textContent = new Date().getFullYear();
  console.log(`🌍 PO ZipCode Global v7 — ${ALL_COUNTRIES.length} countries ready`);
})();
